// Import the Verus standard library
use vstd::prelude::*;

verus! {

    /// Given two non-empty vectors of equal length, returns a new vector
    /// where each element is the bitwise XOR of the corresponding elements.
    ///
    /// Preconditions:
    ///     a.len() == b.len()
    ///     a.len() > 0
    ///
    /// Postcondition:
    ///     result.len() == a.len()
    ///     forall i < a.len(): result[i] == a[i] ^ b[i]
    fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8>
        requires
            a.len() == b.len(),
            a.len() > 0,
        ensures
            |res: Vec<u8>| {
                res.len() == a.len() &&
                forall(|i: usize| i < a.len() ==> res[i] == a[i] ^ b[i])
            }
    {
        let n = a.len();
        // Pre-allocate an empty result vector of capacity n
        let mut res = Vec::with_capacity(n);
        let mut i: usize = 0;

        // Loop to fill `res` with a[i] ^ b[i]
        while i < n
            invariant
                // we never overshoot
                i <= n,
                // res has grown exactly i elements so far
                res.len() == i,
                // for each index j < i, res[j] == a[j] ^ b[j]
                forall(|j: usize| j < i ==> res[j] == a[j] ^ b[j]),
            decreases
                // measure strictly decreases to prove termination
                n - i,
        {
            let ai = a[i];
            let bi = b[i];
            res.push(ai ^ bi);
            i += 1;
        }

        // At this point, i == n and res.len() == n, and the invariant
        // ensures every element is a[i] ^ b[i].
        res
    }

}